  "measure_id": "MEAS-1B4E2E1B",
  "restatements": [
    {
      "clause_id": "§1",
      "text": "Repeals the existing cap on residential rent increases and allows landlords to raise rent by any amount, provided they give 60 days' written notice."
    }
  ],
  "findings": [
    {
